var InvoiceCore=(()=>{
function number(value){if(typeof value==='number')return Number.isFinite(value)?value:null;let s=String(value??'').replace(/[€\s]/g,'').trim();if(!s)return null;if(s.includes(','))s=s.replaceAll('.','').replace(',','.');const n=Number(s);return Number.isFinite(n)&&n>=0?n:null}
function parse(text){const lines=String(text).split(/\r?\n/).map(s=>s.replace(/\s+/g,' ').trim()).filter(Boolean),positions=[],money='([0-9]+(?:[.][0-9]{3})*(?:,[0-9]{2})|[0-9]+[.][0-9]{2})',pattern=new RegExp('^(.+?)\\s+(\\d+(?:[.,]\\d+)?)\\s*(Stk\\.?|Stück|m²|m2|m|kg|l|Liter|Std\\.?|h|Pauschale|pauschal|Pack\\.?|Set|Eimer)\\s+'+money+'(?:\\s+(?:€|EUR))?(?:\\s+'+money+')?','i');for(const line of lines){const m=line.match(pattern);if(m&&!/gesamt|summe|mwst|mehrwertsteuer/i.test(m[1]))positions.push({label:m[1].replace(/^\d+[.)]?\s+/,''),qty:number(m[2]),unit:m[3],unitPrice:number(m[4]),basis:'unknown',vat:null})}let total=null;for(const line of lines){if(/rechnungsbetrag|gesamtbetrag|zahlbetrag|bruttobetrag|endsumme/i.test(line)){const matches=[...line.matchAll(new RegExp(money,'g'))];if(matches.length)total=number(matches.at(-1)[0])}}const joined=lines.join('\n'),invoiceNumber=joined.match(/Rechnung(?:snummer|s-Nr\.?|[-\s]*Nr\.?|s-Nr\.?)[\s:]*([A-Z0-9][A-Z0-9_./-]{1,60})/i)?.[1]||'',d=joined.match(/Rechnungsdatum\s*:?\s*(\d{1,2})\.(\d{1,2})\.(\d{4})/i),date=d?d[3]+'-'+d[2].padStart(2,'0')+'-'+d[1].padStart(2,'0'):'';return {supplier:lines[0]?.slice(0,200)||'',invoiceNumber,date,total,positions}}
function applyValues(position){const qty=number(position.qty),unitPrice=number(position.unitPrice),vat=number(position.vat);if(!qty||unitPrice===null)throw Error('Bitte eine positive Menge und einen gültigen Preis angeben.');if(!['gross','net'].includes(position.basis))throw Error('Bitte bestätigen, ob der Einzelpreis brutto oder netto ist.');if(position.basis==='net'&&(vat===null||vat>100))throw Error('Bitte den Umsatzsteuersatz für den Nettopreis angeben.');return {qty,unit:String(position.unit||'Stk.').slice(0,30),unitPrice:Math.round(unitPrice*(position.basis==='net'?1+vat/100:1)*100)/100}}
return {number,parse,applyValues};})();
if(typeof module!=='undefined')module.exports=InvoiceCore;
